from pathlib import Path

root = Path('.')

def read(p):
    return (root / p).read_text()

def write(p,s):
    (root/p).write_text(s)

def must_replace(text, old, new, path):
    if old not in text:
        raise SystemExit(f'missing in {path}: {old[:120]!r}')
    return text.replace(old, new, 1)

